def apply(inputs, premises):
    base_total = 0
    for fee in inputs["checked_bag_base_fees"]:
        base_total = base_total + int(fee)
    excess_total = 0
    overweight = inputs["checked_bag_overweight_fees"]
    oversize = inputs["checked_bag_oversize_fees"]
    count = max(len(overweight), len(oversize))
    for i in range(count):
        weight_fee = 0
        size_fee = 0
        if i < len(overweight):
            weight_fee = int(overweight[i])
        if i < len(oversize):
            size_fee = int(oversize[i])
        if premises["simultaneous_excess_rule"] == "higher_plus_checked_fee":
            excess_total = excess_total + max(weight_fee, size_fee)
    answer = int(inputs["ticket_price"]) + base_total + excess_total
    return {"answer": answer}
